-- =====================================================================
-- Flyway migration: popula users, orders e products com 100 registros cada
-- IDs EXPLICITOS (1..100) para garantir integridade referencial da FK
-- products.order_id -> orders.id. As sequences sao reposicionadas ao final
-- (RESTART WITH 101) para nao colidir com inserts futuros da aplicacao.
--
-- MAPEAMENTOS (validados com Address.java e enums):
--   * Address @Embedded -> street, number, city, neighborhood, state, cep, complement
--   * users.profile       : ORDINAL -> 1 (USER)
--   * orders.payment_type : ORDINAL -> 0=CREDIT_CARD,1=DEBIT_CARD,2=BOLETO,3=PIX
--   * orders.status       : STRING  -> PENDING_PAYMENT, PROCESSING, SENT, DELIVERED
--   * products.enum_product_category : STRING -> BOOKS, MUSIC, CLOTHES, ACCESSORIES
--   * password            : bcrypt de '123456'
-- =====================================================================

-- ------------------------- USERS (profile = 1 -> USER) -------------------------

-- ------------------------- ORDERS -------------------------

-- ------------------------- PRODUCTS (1 item por order; order_id 1..100) -------------------------

-- ------------------------- Reposiciona as sequences -------------------------
ALTER SEQUENCE users_seq RESTART WITH 151;
ALTER SEQUENCE orders_seq RESTART WITH 151;
ALTER SEQUENCE products_seq RESTART WITH 151;